window.OL_I18N = {"lang":"zh-TW","dict":{"meta.appName":"Openline eSIM 支援查詢","meta.searchTitle":"{q} eSIM 支援度 · Openline","ui.skip":"跳至主要內容","ui.brandAria":"Openline — 查詢裝置相容性","ui.brandSub":"查詢您的裝置是否相容","lang.label":"語言","lang.aria":"變更語言","hero.titleHtml":"您的裝置支援 <span class=\"accent\">eSIM</span> 嗎？","hero.tag":"手機、平板、智慧手錶、行動分享器 — 輸入任何品牌或型號，馬上告訴您能否啟用 Openline。","search.placeholder":"試試「iPhone 18 Pro」、「Galaxy Z Fold8」、「Pixel Watch 5」、「iPad Air」或型號代碼…","search.aria":"搜尋裝置品牌、型號或型號代碼","search.clear":"清除搜尋","stats.devices":"款裝置","stats.compatible":"支援","stats.notCompatible":"不支援","stats.brands":"個品牌","filters.label":"篩選條件","filters.summaryAll":"所有裝置 · 所有品牌","filters.explain":"選擇相容性狀態和／或一個以上的品牌。篩選條件會與搜尋框合併運作，並即時更新下方清單。","filters.compat":"相容性","filters.compatAria":"相容性篩選","filters.brands":"品牌","filters.brandsAria":"品牌篩選","filters.clearAll":"全部清除","filters.compatOnly":"僅顯示支援","filters.notCompatOnly":"僅顯示不支援","filters.allStatuses":"所有狀態","filters.nBrands":{"other":"{n} 個品牌"},"filters.matchHtml":{"other":"符合 <strong>{n}</strong> 款裝置"},"cat.count":{"other":"{n} 款裝置"},"results.all":"所有裝置","results.matching":"符合的裝置","results.ofTotalHtml":"<strong>{n}</strong> 款（共 {total} 款）","results.totalHtml":"共 <strong>{n}</strong> 款","results.showingFirst":" · 僅顯示前 {max} 筆","legend.ok":"支援 eSIM","legend.err":"僅支援實體 SIM 卡","status.ok":"相容","status.no":"不相容","status.okAria":"支援 eSIM","status.noAria":"不支援 eSIM","note.caveatAria":"地區限制：{note}","popover.aria":"地區限制說明","popover.close":"關閉","empty.noMatchTitle":"找不到完全相符的裝置。","empty.noMatchBodyHtml":"請試著只輸入品牌（例如：<em>Samsung</em>）或完整型號（例如：<em>SM-S921B</em>）。若您的裝置為 2021 年後推出，且並非在中國大陸以外地區發售的版本以外的機型，則極有可能支援 eSIM。","empty.bothTitle":"沒有裝置同時符合您的搜尋與篩選條件。","empty.bothBodyHtml":{"other":"搜尋「<em>{q}</em>」共找到 <strong>{n}</strong> 款裝置，但皆不符合目前的篩選條件。是不是篩選條件造成衝突了呢？"},"empty.filtersTitle":"沒有裝置符合目前的篩選條件。","empty.filtersBody":"請試著放寬篩選條件 — 將罕見的相容性狀態與特定品牌組合在一起，可能會找不到任何結果。","empty.nothing":"目前尚無內容。","empty.resetFilters":"重設篩選","empty.clearSearch":"清除搜尋","footer.privacy":"隱私權政策","footer.terms":"服務條款","footer.socialAria":"Openline 社群媒體","footer.onNetwork":"Openline 的 {network}","footer.handleOnNetwork":"{network} 上的 @askopenline","footer.indexedHtml":"已收錄 <b id=\"footer-total\">{n}</b> 款裝置","region.US":"美國","region.HK":"香港","region.CN":"中國大陸","region.KR":"南韓","region.JP":"日本","region.AU":"澳洲","region.TW":"台灣","region.SEA":"東南亞","region.EU":"歐盟","region.IN":"印度","region.UK":"英國","exp.carrierWatch":"行動網路版智慧手錶需透過電信業者的手錶方案取得 eSIM，並透過配對手機上的配套應用程式（Apple Watch App、Galaxy Wearable、Pixel Watch App）進行設定。手機或旅遊用 eSIM 的 QR code 無法直接安裝在手錶上，請先確認您的電信業者是否提供適用此手錶的方案。","exp.gpsOnly":"此為僅 GPS 版本，沒有行動網路模組，因此無法使用任何 eSIM。同款手錶的 GPS + 行動網路版型號不同。","exp.cnHkMoDualNano":"此世代在中國大陸、香港及澳門販售的 iPhone 具備兩個實體 nano-SIM 卡槽，不支援 eSIM，因此無法安裝 Openline。請在「設定 › 一般 › 關於本機」中查看型號。","exp.cnDualNano":"此手機的中國大陸版本使用兩張實體 nano-SIM 卡，不支援 eSIM；其他地區販售的機型則支援 eSIM。請在「設定 › 一般 › 關於本機」中查看型號。","exp.cnLocalRules":"中國大陸版本支援 eSIM，但中國電信業者僅在門市經身分查驗後才會啟用 eSIM，且身處中國大陸期間無法安裝境外 eSIM 設定檔。在中國境外，Openline 等旅遊 eSIM 可正常安裝。","exp.esimOnlyUsJpCaGulf":"在美國、加拿大、日本、墨西哥及海灣國家販售的機型沒有 SIM 卡槽，僅支援 eSIM。其他地區的機型另配有 nano-SIM 卡槽，而中國大陸版可能不支援 eSIM。Openline 適用於所有支援 eSIM 的版本。","exp.noSimTray":"此版本沒有實體 SIM 卡槽：包含 Openline 在內的所有門號都以 eSIM 方式加入。您可以儲存多組 eSIM，並在「設定」中切換。","exp.iden":"此裝置使用 Motorola 的 iDEN 網路（Nextel / Boost 即按即說），Sprint 已於 2013 年 6 月完全終止該網路。此裝置無法連上任何現代行動網路，無論是否使用 eSIM，僅具博物館／收藏價值。","exp.cdmaVerizon":"此為僅支援 CDMA 的裝置，專為 Verizon 舊版 2G/3G CDMA 網路打造，該網路已於 2022 年 12 月 31 日關閉。此裝置完全沒有 SIM 卡槽（不論實體或 eSIM）— CDMA 是透過裝置的 ESN/MEID 而非 SIM 進行網路驗證。無法搭配 Openline 或任何現代電信業者使用。","exp.cdmaSprint":"此為專為 Sprint 舊版網路打造的 CDMA 裝置，T-Mobile 已於 2022 年 5 月 31 日永久關閉該網路。較新的 Sprint 機型加入了 LTE/GSM，但早期機型僅支援 CDMA，無法連上任何現代網路，不論是否使用 eSIM。","exp.sunset":"此裝置依賴電信業者已關閉的 3G 或早期 4G 網路（AT&T 3G 於 2022 年 2 月終止，T-Mobile 於 2022 年 2 月，Verizon 於 2022 年 12 月，多數歐洲 3G 於 2025 年前終止）。即使有可用的 SIM 卡槽，在多數國家也已沒有可連線的網路。","exp.windowsPhone":"此裝置執行 Windows Phone（或 Windows 10 Mobile），微軟已於 2019 年停止支援 — 應用程式商店、安全性更新與多數原廠服務均已關閉。此裝置沒有 eSIM 硬體，也幾乎沒有現代 App 支援，無法作為日常手機使用。","exp.kaios":"此為 KaiOS 功能型手機。幾乎所有 KaiOS 裝置都不支援 eSIM — 它們使用實體 SIM 卡（通常為 nano-SIM），主打印度（JioPhone）與非洲等僅支援 4G 的平價功能型手機市場。無法在此安裝 Openline。","exp.telematics":"此為車載資通訊模組（Tesla、BMW、Audi 等），其原廠內建 eSIM 直接焊接在車輛連網電路板上。該 eSIM 由車廠於出廠時配置，無法換成 Openline 這類由使用者安裝的設定檔，也無法由使用者自行維修。","exp.satellite":"此為衛星／GPS 通訊裝置（Garmin inReach、SPOT、Zoleo、Iridium GO），使用 Iridium 或 Globalstar 衛星網路，而非 GSM/LTE 行動網路。它無法使用一般意義上的 eSIM，連線功能綁定於裝置製造商的專屬訂閱服務。","exp.medical":"此為醫療警報或個人緊急救援（PERS）裝置。其行動通訊模組鎖定於特定服務供應商（Lively、Medical Guardian、Life Alert、Bay Alarm），只能搭配其監控訂閱服務使用，無法安裝第三方 eSIM。","exp.rugged":"此為 Samsung 企業／強固型（Galaxy XCover 系列）裝置，專為倉儲、醫療、旅宿等第一線工作人員設計。此機型支援 eSIM，但啟用可能需透過雇主的 Samsung Knox MDM 設定。若裝置已解鎖，Openline 的安裝方式與一般消費型手機相同。","exp.harmony":"此裝置執行華為 HarmonyOS，沒有 Google 行動服務。啟用 eSIM 通常需要華為 EMUI/HarmonyOS 的電信服務 App；Openline 設定檔可透過 QR code 配置，但無法透過 Google 錢包啟用。在中國大陸販售的機型也可能因中國韌體限制而拒絕國際 eSIM 設定檔。","exp.dualEsimOnly":"此版本可同時支援兩組 eSIM，但沒有實體 SIM 卡槽。Openline 可正常使用 — 只是無法與 nano-SIM 搭配。在部分地區版本中，一次只能啟用一組 eSIM。","exp.euCarrier":"此裝置部分歐洲電信業者鎖定版本在出廠時於韌體層級停用了 eSIM。已解鎖／全球公開版則可正常支援 eSIM。若無法啟用，請洽詢您原本的電信業者。","exp.usCarrier":"此為美國電信業者品牌版本（AT&T、T-Mobile、Verizon、Sprint），韌體受到鎖定，且通常僅支援特定業者的頻段。eSIM 可能被停用，或僅限使用該品牌業者的設定檔。同型號的已解鎖國際版通常可搭配 Openline 使用，電信業者品牌版則不一定。","exp.verizon":"此款 Pixel 的 Verizon 品牌版本在上市時，於 Verizon 網路上停用了 eSIM。已解鎖版與非 Verizon 業者的版本可正常支援 eSIM。","exp.googleFi":"在這個世代的 Pixel 上，美國僅能透過 Google Fi 使用 eSIM，其他業者只能使用實體 SIM 卡。全球已解鎖版則在各地都支援 eSIM。","exp.usEsimOnly":"在美國購買的這款 iPhone，Apple 已完全移除實體 SIM 卡槽 — 必須使用 eSIM。在其他地區，手機除了 eSIM 外還配有實體 SIM 卡槽。無論哪種版本，Openline 都能使用。","exp.cnOnly":"此裝置搭載中國境內版韌體。規格上雖支援 eSIM，但在中國大陸境外，國際設定檔經常無法啟用。若您打算出國旅行，購買前請先向賣家確認 eSIM 的啟用情況。","exp.jpDomestic":"日本電信業者品牌手機（NTT DoCoMo、au、SoftBank、Rakuten）通常鎖定日本的頻段規劃。eSIM 硬體在日本可正常運作；在海外能否啟用，取決於頻段是否與當地網路重疊。","exp.regionLocked":"此裝置的 eSIM 啟用功能在韌體層級受到地區鎖定，只接受其販售國家／地區電信業者的 eSIM 設定檔。","exp.krOnly":"此型號僅在南韓販售，使用 KT/SKT/LGU+ 的電信頻段。雖具備 eSIM 硬體，但在海外啟用並不穩定。","exp.foldable":"此為摺疊式裝置 — 具備 eSIM 功能，但請注意，部分在中國販售的摺疊機版本不支援國際 eSIM。請確認型號代碼與全球版 SKU 相符。","exp.hotspot":"此為可攜式 Wi-Fi 分享器／MiFi 路由器，而非手機。它可安裝 eSIM，將行動數據分享給您的其他裝置。Openline 的配置方式與手機相同。","exp.simTrayOnly":"此裝置具備行動網路模組，但只接受實體 nano-SIM 或 micro-SIM — 沒有 eSIM 晶片。您無法在此安裝 Openline eSIM，需改用實體 SIM 卡方案。","exp.wifiOnly":"此版本僅支援 Wi-Fi，沒有行動網路數據機，無法安裝任何 eSIM。請尋找同型號的 LTE / 5G / 行動網路版。","exp.ereader":"此為電子書閱讀器，內建與製造商免費數據方案綁定的行動網路數據機（Amazon Whispernet、B&N nook 等）。其 eSIM/SIM 無法由使用者自行配置 — 無法換成 Openline 設定檔。","exp.cellularEsimOnly":"此版本僅透過 eSIM 提供行動網路連線 — 裝置上沒有實體 SIM 卡槽。Openline 可直接透過 QR code 安裝。","exp.unverifiedVariant":"我們的資料將此型號代碼對應到多個產品系列。這通常表示 Apple/Samsung/Google 在不同世代重複使用了內部編號，或某個地區版 SKU 曾被更名。Openline 應該仍可使用，但若外盒上的型號與您手上的裝置不符，購買前請先向製造商確認。","exp.crossBrand":"此型號代碼也出現在其他品牌的裝置上（Vivo/iQOO、Xiaomi/POCO、Nokia/HMD、Nubia/ZTE 等）。這通常是同集團的姊妹品牌 — 硬體往往相同，有時只是換標重新販售 — 但兩個品牌的 eSIM 支援與電信認證可能不同。請以您裝置實際的零售包裝為準。","exp.modelUnverified":"我們沒有此裝置的權威型號／零件編號 — 通常是因為它是穿戴裝置、車載資通訊裝置、行動分享器或配件，其 SKU 並未公開。製造商規格表上有標示 eSIM 支援，但 Openline 無法比對特定硬體代碼來保證相容性。使用前請先向製造商確認。","exp.ambiguous":"此處的產品名稱非常短（「13」、「F7」、「M6」…），容易與其他品牌或其他世代的同數字型號混淆。請檢查裝置上的品牌與型號代碼，確認此項目確實與您的裝置相符。","exp.cnFirmware":"此機型搭載中國境內版韌體。雖具備 eSIM 硬體，但中國版韌體經常會阻擋國際 eSIM 設定檔啟用。若您打算在中國大陸境外使用 Openline，購買前請先向賣家確認韌體沒有地區鎖定。","exp.regionExcluded":"此裝置在以下地區販售的版本沒有 eSIM 硬體，只能使用實體 SIM 卡槽：{regions}。其他地區皆支援 eSIM，Openline 可正常啟用。若您的裝置購自海外或水貨／平行輸入業者，請對照製造商的清單確認型號。","note.3G free":"免費 3G","note.3G/4G":"3G/4G","note.AU/JP/TW excluded":"AU/JP/TW 不支援","note.Ambiguous name":"名稱易混淆","note.CDMA":"CDMA","note.CN firmware":"CN 韌體","note.CN/HK excluded":"CN/HK 不支援","note.CN/HK/MO: dual nano-SIM":"CN/HK/MO：雙 nano-SIM","note.CN/IN":"CN/IN","note.CN/IN dual-eSIM only":"CN/IN 僅雙 eSIM","note.CN: dual nano-SIM":"CN：雙 nano-SIM","note.CN: local eSIM rules":"CN：當地 eSIM 規定","note.Carrier watch plan":"手錶電信方案","note.Cross-brand model code":"跨品牌型號代碼","note.E-reader":"電子書閱讀器","note.Enterprise rugged":"企業強固型","note.Foldable":"摺疊機","note.GPS only":"僅 GPS","note.GPS/satellite tracker":"GPS／衛星追蹤器","note.Google Fi/US only":"僅限美國 Google Fi","note.HarmonyOS":"HarmonyOS","note.JP domestic band lock":"JP 國內頻段鎖定","note.KR only":"僅限 KR","note.KR/CN":"KR/CN","note.KaiOS feature phone":"KaiOS 功能型手機","note.Medical alert":"醫療警報裝置","note.Mobile hotspot":"行動分享器","note.Model code unverified":"型號代碼未驗證","note.Nextel/Boost":"Nextel/Boost","note.No eSIM hardware":"無 eSIM 硬體","note.No eSIM in most regions":"多數地區無 eSIM","note.Not on Verizon/Sprint":"Verizon/Sprint 不支援","note.SEA excluded":"SEA 不支援","note.SIM tray only":"僅 SIM 卡槽","note.Sprint":"Sprint","note.US carrier variant":"美國電信版","note.US model excluded":"美版不支援","note.US variant excluded":"美版不支援","note.US/HK excluded":"US/HK 不支援","note.US/JP: eSIM ok":"US/JP：支援 eSIM","note.US: eSIM only":"US：僅 eSIM","note.Unverified variant":"版本未驗證","note.Vehicle telematics":"車載資通訊","note.Verizon":"Verizon","note.Verizon US no eSIM":"Verizon 美版無 eSIM","note.Verizon-only 5G":"僅限 Verizon 5G","note.Wi-Fi + Cellular only":"僅 Wi-Fi + 行動網路","note.Wi-Fi + free 4G":"Wi-Fi + 免費 4G","note.Wi-Fi only":"僅 Wi-Fi","note.Wi-Fi only in most regions":"多數地區僅 Wi-Fi","note.Wi-Fi/3G":"Wi-Fi/3G","note.Windows Phone":"Windows Phone","note.deprecated":"已淘汰","note.dual-eSIM in EU":"歐版支援雙 eSIM","note.eSIM only":"僅 eSIM","note.eSIM only (no SIM tray)":"僅 eSIM（無 SIM 卡槽）","note.eSIM only in US/JP/CA/Gulf":"US/JP/CA/海灣僅 eSIM","note.eSIM only via Google Fi":"僅限 Google Fi eSIM","note.iDEN":"iDEN","note.sunset":"已終止服務"}};
